//! Frozen native-prefix BTreeMap dispatcher before contiguous callback storage.
//! Screen-owned native Lua input callbacks. ScreenManager sends these after
//! normal screen input; a truthy callback stops other callbacks, not gameplay.
use mlua::{Function, Lua, Table, Value};
use std::collections::BTreeMap;
use std::ops::Bound::{Excluded, Unbounded};

#[path = "../../src/input/compiled.rs"]
mod compiled;
pub use compiled::SongLuaCompiledInput;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SongLuaInputType {
    FirstPress,
    Repeat,
    Release,
}

impl SongLuaInputType {
    fn native_name(self) -> &'static str {
        match self {
            Self::FirstPress => "InputEventType_FirstPress",
            Self::Repeat => "InputEventType_Repeat",
            Self::Release => "InputEventType_Release",
        }
    }
}

/// Inputs supplied by the input owner, never inferred from expected Lua output.
#[derive(Clone, Debug)]
pub struct SongLuaInputEvent<'a> {
    pub player: Option<usize>,
    pub controller: Option<usize>,
    pub button: &'a str,
    pub game_button: &'a str,
    pub kind: SongLuaInputType,
    pub device: &'a str,
    pub device_button: &'a str,
    pub level: f32,
    pub z: i32,
    pub down: bool,
    pub ago: f64,
    pub is_joystick: bool,
    pub is_mouse: bool,
}

#[derive(Default)]
struct Callbacks {
    functions: BTreeMap<usize, Callback>,
    dispatching: bool,
    removals: Vec<usize>,
}

struct Callback {
    function: Function,
    native: Option<SongLuaCompiledInput>,
}

// Sticky across callback removal and screen replacement: an offline sample
// cannot represent external input, even if its discovery probe later removes it.
#[derive(Default)]
struct RequiresRuntime;

pub(crate) fn require_offline_compatible(lua: &Lua) -> Result<(), String> {
    if lua.app_data_ref::<RequiresRuntime>().is_some() {
        Err(
            "song Lua registers input callbacks and requires runtime Lua (context.live = true)"
                .into(),
        )
    } else {
        Ok(())
    }
}

pub(crate) fn install(lua: &Lua, screen: &Table) -> mlua::Result<()> {
    // A gameplay reload retains the VM but replaces Screen's callback map.
    lua.set_app_data(Callbacks::default());
    screen.set(
        "AddInputCallback",
        lua.create_function(|lua, (screen, callback): (Table, Function)| {
            lua.set_app_data(RequiresRuntime);
            let key = callback.to_pointer() as usize;
            let native = SongLuaCompiledInput::compile(&callback);
            let mut callbacks = lua
                .app_data_mut::<Callbacks>()
                .expect("screen callback registry");
            callbacks.functions.insert(
                key,
                Callback {
                    function: callback,
                    native,
                },
            );
            Ok(screen)
        })?,
    )?;
    screen.set(
        "RemoveInputCallback",
        lua.create_function(|lua, (screen, callback): (Table, Function)| {
            let mut callbacks = lua
                .app_data_mut::<Callbacks>()
                .expect("screen callback registry");
            let key = callback.to_pointer() as usize;
            if callbacks.dispatching {
                callbacks.removals.push(key);
            } else {
                callbacks.functions.remove(&key);
            }
            Ok(screen)
        })?,
    )
}

pub(crate) fn dispatch(
    lua: &Lua,
    input: &SongLuaInputEvent<'_>,
) -> mlua::Result<(bool, Vec<String>)> {
    let mut previous = None;
    if !lua.has_hook() {
        let mut callbacks = lua
            .app_data_mut::<Callbacks>()
            .expect("screen callback registry");
        // Reentrant dispatch retains the existing deferred-removal protocol.
        if !callbacks.dispatching {
            if callbacks.functions.is_empty() {
                return Ok((false, Vec::new()));
            }
            if callbacks
                .functions
                .first_key_value()
                .is_some_and(|(_, callback)| callback.native.is_some())
            {
                let frame = compiled::Frame::new(input);
                let values = frame.values(input);
                let mut all_native = true;
                for (&key, callback) in &mut callbacks.functions {
                    let Some(native) = callback.native.as_mut() else {
                        all_native = false;
                        break;
                    };
                    previous = Some(key);
                    if native.evaluate_frame(&values) {
                        return Ok((true, Vec::new()));
                    }
                }
                if all_native {
                    return Ok((false, Vec::new()));
                }
            }
        }
    }
    // Input-only callbacks cannot mutate the event or registry. A false native
    // prefix leaves the original input untouched. Once Lua runs, all remaining
    // callbacks use its shared mutable event, including otherwise compiled ones.
    let event = create_event(lua, input)?;
    lua.app_data_mut::<Callbacks>()
        .expect("screen callback registry")
        .dispatching = true;
    let mut handled = false;
    let mut errors = Vec::new();
    loop {
        let next = {
            let callbacks = lua
                .app_data_ref::<Callbacks>()
                .expect("screen callback registry");
            match previous {
                Some(key) => callbacks.functions.range((Excluded(key), Unbounded)).next(),
                None => callbacks.functions.iter().next(),
            }
            .map(|(&key, callback)| (key, callback.function.clone()))
        };
        let Some((key, callback)) = next else {
            break;
        };
        previous = Some(key);
        match callback.call::<Value>(event.clone()) {
            Ok(value) => handled = !matches!(value, Value::Nil | Value::Boolean(false)),
            Err(error) => errors.push(format!("Error running input callback: {error}")),
        }
        if handled {
            break;
        }
    }
    let mut callbacks = lua
        .app_data_mut::<Callbacks>()
        .expect("screen callback registry");
    callbacks.dispatching = false;
    let removals = std::mem::take(&mut callbacks.removals);
    for key in removals {
        callbacks.functions.remove(&key);
    }
    Ok((handled, errors))
}

// Fresh tables cannot have authored metamethods. Keep the original insertion
// and conversion order, including nil writes, without changing hash capacity.
pub(crate) fn create_event(lua: &Lua, input: &SongLuaInputEvent<'_>) -> mlua::Result<Table> {
    use mlua::Either::{Left, Right};
    let event = lua.create_table()?;
    let device = lua.create_table()?;
    device.raw_set_many([
        ("device", Left(input.device)),
        ("button", Left(input.device_button)),
        ("level", Right(Value::Number(f64::from(input.level)))),
        ("z", Right(Value::Integer(input.z.into()))),
        ("down", Right(Value::Boolean(input.down))),
        ("ago", Right(Value::Number(input.ago))),
        ("is_joystick", Right(Value::Boolean(input.is_joystick))),
        ("is_mouse", Right(Value::Boolean(input.is_mouse))),
    ])?;
    let mut device = Some(device);
    event.raw_set_many((0..7).map(|index| match index {
        0 => (
            "DeviceInput",
            Right(Value::Table(device.take().expect("first event field"))),
        ),
        1 => (
            "controller",
            input.controller.map_or(Right(Value::Nil), |p| {
                Left(Right(format!("GameController_{}", p + 1)))
            }),
        ),
        2 => ("button", Left(Left(input.button))),
        3 => ("GameButton", Left(Left(input.game_button))),
        4 => ("type", Left(Left(input.kind.native_name()))),
        5 => (
            "PlayerNumber",
            input.player.map_or(Right(Value::Nil), |p| {
                Left(Right(format!("PlayerNumber_P{}", p + 1)))
            }),
        ),
        _ => ("MultiPlayer", Right(Value::Nil)),
    }))?;
    Ok(event)
}

rejected_initializer_source.final-registers-mod.rs:
//! Native execution of a verified, finite subset of Lua 5.1 callbacks.
//!
//! Loading uses Lua to produce bytecode. Compilation binds object fields and
//! actions to a closed native schema, then discards all Lua handles. Programs
//! process new inputs and keep mutable scalar state between calls. Unsupported
//! operations fail compilation before any callback body is executed.
//!
//! Bindings describe semantics established by the host: object identities,
//! raw fields without metamethods, action identity/arity/results, and explicit
//! shared cells. The compiler cannot infer these promises from field names or
//! equal captured values. Hosts must validate them against their Lua objects.
//! These contracts must hold for every call, including action side effects.
//! Mutable captures must be private to this machine; another callback or live
//! Lua object must not observe or change their former storage. Cells are shared
//! within one machine, not between independent machines. Actions cannot change
//! inputs or native cells indirectly, and must have the declared static return.
//! Mutable cells keep one fixed boolean or number type. String/number coercion,
//! dynamic lookup, object equality, loops and general Lua calls are unsupported.
//! An input frame is immutable for a complete call. Action arguments borrow
//! its bytes or the program's owned constants without allocating.

mod compile;
mod decode;

use crate::Function;
use std::{
    fmt,
    mem::{size_of, size_of_val},
    ops::{BitOr, BitOrAssign},
    sync::Arc,
};

/// A set of accepted native value types.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Types(u8);
impl Types {
    pub const NIL: Self = Self(1);
    pub const BOOLEAN: Self = Self(2);
    pub const NUMBER: Self = Self(4);
    pub const BYTES: Self = Self(8);
    pub const OBJECT: Self = Self(16);
    pub const ACTION: Self = Self(32);
    pub const ANY: Self = Self(63);
    const PRIMITIVE: Self = Self(15);
    fn accepts(self, actual: Self) -> bool {
        actual.0 != 0 && actual.0 & !self.0 == 0
    }
}
impl BitOr for Types {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self {
        Self(self.0 | rhs.0)
    }
}
impl BitOrAssign for Types {
    fn bitor_assign(&mut self, rhs: Self) {
        self.0 |= rhs.0;
    }
}

/// Owned literal used while binding a program.
#[derive(Clone, Debug)]
pub enum Literal {
    Nil,
    Boolean(bool),
    Number(f64),
    Bytes(Box<[u8]>),
}

/// Initial value and fixed type of one explicit mutable cell.
#[derive(Clone, Copy, Debug)]
pub enum Cell {
    Boolean(bool),
    Number(f64),
}

/// Source of a parameter, capture or bound field.
#[derive(Clone, Debug)]
pub enum Binding {
    Literal(Literal),
    Object(u32),
    Cell(usize),
    Input { slot: usize, types: Types },
}

/// A host action with checked argument types and a statically known return.
/// Its effects must preserve the remaining bindings; native cells change only
/// through compiled writes. Action failures and dynamic results are unsupported.
#[derive(Clone, Debug)]
pub struct Action {
    pub tag: u32,
    pub parameters: Vec<Parameter>,
    /// None means no return values. Only literal and object bindings are accepted.
    pub result: Option<Binding>,
}

/// A host action's parameter contract. Object constraints preserve receiver
/// identity when lowering methods whose implementation depends on `self`.
#[derive(Clone, Copy, Debug)]
pub enum Parameter {
    Type(Types),
    Object(u32),
}

/// A field may be a value, a mutable cell, or a bound host action.
#[derive(Clone, Debug)]
pub enum FieldValue {
    Value(Binding),
    Action(Action),
}

/// A field of an opaque, host-validated object.
#[derive(Clone, Debug)]
pub struct Field {
    pub object: u32,
    pub name: Box<[u8]>,
    pub value: FieldValue,
}

/// Complete native schema for one callback. Repeated cell indices or object
/// identities express aliasing; distinct indices are never merged by value.
#[derive(Clone, Debug, Default)]
pub struct Bindings {
    pub arguments: Vec<Binding>,
    pub upvalues: Vec<Binding>,
    pub cells: Vec<Cell>,
    pub fields: Vec<Field>,
    pub environment: Option<u32>,
}

/// Rejection at compilation; no authored callback body has run.
#[derive(Debug)]
pub enum CompileError {
    InvalidChunk,
    InvalidBindings(&'static str),
    Unsupported { pc: usize, reason: &'static str },
    Dump(String),
}
impl fmt::Display for CompileError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "native Lua callback compilation: {self:?}")
    }
}
impl std::error::Error for CompileError {}

/// A malformed input frame. Compiled code and mutable state remain memory safe;
/// actions/state changes preceding the failing read are not rolled back.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RunError {
    MissingInput(usize),
    InputType(usize),
}
impl fmt::Display for RunError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "native Lua input: {self:?}")
    }
}
impl std::error::Error for RunError {}

/// Native inputs, results and action arguments. Opaque IDs refer to the host's
/// validated bindings, not Lua pointers. Byte slices may contain arbitrary data.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Datum<'a> {
    Nil,
    Boolean(bool),
    Number(f64),
    Bytes(&'a [u8]),
    Object(u32),
    Action(u32),
}
impl Datum<'_> {
    pub fn is_truthy(self) -> bool {
        !matches!(self, Self::Nil | Self::Boolean(false))
    }
    fn types(self) -> Types {
        match self {
            Self::Nil => Types::NIL,
            Self::Boolean(_) => Types::BOOLEAN,
            Self::Number(_) => Types::NUMBER,
            Self::Bytes(_) => Types::BYTES,
            Self::Object(_) => Types::OBJECT,
            Self::Action(_) => Types::ACTION,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Value {
    Nil,
    Boolean(bool),
    Number(u64),
    String(usize),
    InputString(usize),
    Object(u32),
    Action(u32),
}
impl Value {
    fn types(self) -> Types {
        match self {
            Self::Nil => Types::NIL,
            Self::Boolean(_) => Types::BOOLEAN,
            Self::Number(_) => Types::NUMBER,
            Self::String(_) | Self::InputString(_) => Types::BYTES,
            Self::Object(_) => Types::OBJECT,
            Self::Action(_) => Types::ACTION,
        }
    }
    fn truthy(self) -> bool {
        !matches!(self, Self::Nil | Self::Boolean(false))
    }
    fn number(self) -> f64 {
        let Self::Number(bits) = self else {
            unreachable!("verified numeric operand")
        };
        f64::from_bits(bits)
    }
}

#[derive(Clone, Copy, Debug)]
enum Source {
    Value(Value),
    Cell(usize),
    Input(usize, Types),
}
#[derive(Clone, Copy, Debug)]
enum Operand {
    Register(usize),
    Value(Value),
}
impl Operand {
    fn get(self, registers: &[Value]) -> Value {
        match self {
            Self::Register(r) => registers[r],
            Self::Value(v) => v,
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum Op {
    Unreachable,
    Load {
        dst: usize,
        source: Source,
        skip: bool,
    },
    Move {
        dst: usize,
        source: usize,
    },
    Nil {
        first: usize,
        last: usize,
    },
    Write {
        cell: usize,
        source: Operand,
    },
    Method {
        dst: usize,
        receiver: usize,
        action: u32,
    },
    Not {
        dst: usize,
        source: usize,
    },
    Neg {
        dst: usize,
        source: usize,
    },
    Arithmetic {
        dst: usize,
        left: Operand,
        right: Operand,
        operator: u8,
    },
    Compare {
        left: Operand,
        right: Operand,
        operator: u8,
        expected: bool,
    },
    Test {
        source: usize,
        expected: bool,
        copy: Option<usize>,
    },
    Jump(usize),
    Call {
        tag: u32,
        first: usize,
        count: usize,
        dst: Option<usize>,
        result: Value,
        tail: bool,
    },
    Return(Option<usize>),
}

struct Code {
    ops: Box<[Op]>,
    strings: Box<[Box<[u8]>]>,
    cells: Box<[Value]>,
    parameters: Box<[Source]>,
    initial_nil: Box<[u8]>,
    registers: usize,
}

/// Immutable compiled callback. It contains Rust-owned code/data and no Lua
/// handle, registry reference, callback or state pointer.
#[derive(Clone)]
pub struct Program(Arc<Code>);
impl fmt::Debug for Program {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Program")
            .field("instructions", &self.0.ops.len())
            .field("cells", &self.0.cells.len())
            .finish()
    }
}

/// Compile a Lua closure using a validated native schema.
pub fn compile(function: &Function, bindings: &Bindings) -> Result<Program, CompileError> {
    if function.environment().is_none() {
        return Err(CompileError::Unsupported {
            pc: 0,
            reason: "native closure",
        });
    }
    let bytes = function
        .try_dump(false)
        .map_err(|error| CompileError::Dump(error.to_string()))?;
    compile_bytecode(&bytes, bindings)
}

/// Safely decode and compile a Lua 5.1 dump. These bytes are never loaded into
/// Lua. Headers and reachable operands/control flow are validated. Unsupported
/// opcodes and noncanonical constants are rejected.
pub fn compile_bytecode(bytes: &[u8], bindings: &Bindings) -> Result<Program, CompileError> {
    compile::lower(decode::decode(bytes)?, bindings)
}

impl Program {
    /// Create independent mutable state and reusable register storage.
    pub fn machine(&self) -> Machine {
        Machine {
            program: self.clone(),
            cells: self.0.cells.to_vec().into_boxed_slice(),
            registers: vec![Value::Nil; self.0.registers].into_boxed_slice(),
        }
    }

    /// Owned code/data payload, excluding allocator bookkeeping and Arc counters.
    pub fn retained_bytes(&self) -> usize {
        size_of::<Code>()
            + size_of_val(self.0.ops.as_ref())
            + size_of_val(self.0.cells.as_ref())
            + size_of_val(self.0.parameters.as_ref())
            + self.0.initial_nil.len()
            + size_of_val(self.0.strings.as_ref())
            + self.0.strings.iter().map(|s| s.len()).sum::<usize>()
    }
}

/// A borrowed action argument view; it creates no intermediate collection.
pub struct Arguments<'a> {
    values: &'a [Value],
    code: &'a Code,
    inputs: &'a [Datum<'a>],
}
impl<'a> Arguments<'a> {
    pub fn len(&self) -> usize {
        self.values.len()
    }
    pub fn is_empty(&self) -> bool {
        self.values.is_empty()
    }
    pub fn get(&self, index: usize) -> Option<Datum<'a>> {
        self.values.get(index).map(|v| datum(*v, self.code, self.inputs))
    }
}

/// A callback's explicit state and scratch space. Calls allocate no engine
/// storage; host actions may allocate according to the host's own policy.
pub struct Machine {
    program: Program,
    cells: Box<[Value]>,
    registers: Box<[Value]>,
}
impl Machine {
    /// Owned payload including code/data once; excludes allocator bookkeeping.
    pub fn retained_bytes(&self) -> usize {
        size_of::<Self>()
            + self.program.retained_bytes()
            + size_of_val(self.cells.as_ref())
            + size_of_val(self.registers.as_ref())
    }

    /// Observe a scalar cell without exposing mutable or Lua-backed storage.
    pub fn cell(&self, index: usize) -> Option<Datum<'_>> {
        self.cells.get(index).map(|v| datum(*v, &self.program.0, &[]))
    }

    /// Execute against actual immutable inputs and emit host actions in authored
    /// order. The result is the first returned value (nil for no results).
    pub fn run<'a>(
        &'a mut self,
        inputs: &'a [Datum<'a>],
        mut emit: impl FnMut(u32, Arguments<'_>),
    ) -> Result<Datum<'a>, RunError> {
        let code = &self.program.0;
        let registers = &mut self.registers;
        // Lua entry nils are explicit where needed. Other reads have a
        // dominating write, including calls after an input-contract error.
        for &register in &code.initial_nil {
            registers[usize::from(register)] = Value::Nil;
        }
        for (dst, source) in code.parameters.iter().enumerate() {
            registers[dst] = read(*source, &self.cells, inputs)?;
        }
        let mut pc = 0;
        loop {
            let op = code.ops[pc];
            pc += 1;
            match op {
                Op::Unreachable => unreachable!("verified control flow"),
                Op::Load { dst, source, skip } => {
                    registers[dst] = read(source, &self.cells, inputs)?;
                    pc += usize::from(skip);
                }
                Op::Move { dst, source } => registers[dst] = registers[source],
                Op::Nil { first, last } => registers[first..=last].fill(Value::Nil),
                Op::Write { cell, source } => self.cells[cell] = source.get(registers),
                Op::Method {
                    dst,
                    receiver,
                    action,
                } => {
                    let value = registers[receiver];
                    registers[dst + 1] = value;
                    registers[dst] = Value::Action(action);
                }
                Op::Not { dst, source } => registers[dst] = Value::Boolean(!registers[source].truthy()),
                Op::Neg { dst, source } => {
                    registers[dst] = Value::Number((-registers[source].number()).to_bits())
                }
                Op::Arithmetic {
                    dst,
                    left,
                    right,
                    operator,
                } => {
                    let (a, b) = (left.get(registers).number(), right.get(registers).number());
                    registers[dst] = Value::Number(
                        match operator {
                            12 => a + b,
                            13 => a - b,
                            14 => a * b,
                            15 => a / b,
                            _ => unreachable!(),
                        }
                        .to_bits(),
                    );
                }
                Op::Compare {
                    left,
                    right,
                    operator,
                    expected,
                } => {
                    let (a, b) = (left.get(registers), right.get(registers));
                    let equal = match operator {
                        23 => equal(a, b, code, inputs),
                        24 => a.number() < b.number(),
                        25 => a.number() <= b.number(),
                        _ => unreachable!(),
                    };
                    if equal != expected {
                        pc += 1;
                    }
                }
                Op::Test {
                    source,
                    expected,
                    copy,
                } => {
                    if registers[source].truthy() == expected {
                        if let Some(dst) = copy {
                            registers[dst] = registers[source];
                        }
                    } else {
                        pc += 1;
                    }
                }
                Op::Jump(target) => pc = target,
                Op::Call {
                    tag,
                    first,
                    count,
                    dst,
                    result,
                    tail,
                } => {
                    emit(
                        tag,
                        Arguments {
                            values: &registers[first..first + count],
                            code,
                            inputs,
                        },
                    );
                    if tail {
                        return Ok(datum(result, code, inputs));
                    }
                    if let Some(dst) = dst {
                        registers[dst] = result;
                    }
                }
                Op::Return(source) => {
                    return Ok(datum(source.map_or(Value::Nil, |i| registers[i]), code, inputs));
                }
            }
        }
    }
}

fn read(source: Source, cells: &[Value], inputs: &[Datum<'_>]) -> Result<Value, RunError> {
    Ok(match source {
        Source::Value(v) => v,
        Source::Cell(i) => cells[i],
        Source::Input(i, expected) => {
            let v = *inputs.get(i).ok_or(RunError::MissingInput(i))?;
            if !expected.accepts(v.types()) {
                return Err(RunError::InputType(i));
            }
            match v {
                Datum::Nil => Value::Nil,
                Datum::Boolean(v) => Value::Boolean(v),
                Datum::Number(v) => Value::Number(v.to_bits()),
                Datum::Bytes(_) => Value::InputString(i),
                Datum::Object(_) | Datum::Action(_) => unreachable!("primitive input schema"),
            }
        }
    })
}

fn datum<'a>(v: Value, code: &'a Code, inputs: &'a [Datum<'a>]) -> Datum<'a> {
    match v {
        Value::Nil => Datum::Nil,
        Value::Boolean(v) => Datum::Boolean(v),
        Value::Number(bits) => Datum::Number(f64::from_bits(bits)),
        Value::String(i) => Datum::Bytes(&code.strings[i]),
        Value::InputString(i) => inputs[i],
        Value::Object(i) => Datum::Object(i),
        Value::Action(i) => Datum::Action(i),
    }
}

fn equal(a: Value, b: Value, code: &Code, inputs: &[Datum<'_>]) -> bool {
    match (datum(a, code, inputs), datum(b, code, inputs)) {
        (Datum::Nil, Datum::Nil) => true,
        (Datum::Boolean(a), Datum::Boolean(b)) => a == b,
        (Datum::Number(a), Datum::Number(b)) => a == b,
        (Datum::Bytes(a), Datum::Bytes(b)) => a == b,
        _ => false,
    }
}

